import{_ as i,a0 as o,w as r,s as d,ao as e,I as a,x as n,a1 as l,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"3 個 Python 模板庫比較 | LCTT x X-CMD","titleTemplate":false,"description":"3 個 Python 模板庫比較 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 個 Python 模板庫比較 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 個 Python 模板庫比較 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180427 3 Python template libraries compared","title":"3 個 Python 模板庫比較","tag":"201806","desc":""},"relativePath":"201806/20180427 3 Python template libraries compared.md","filePath":"[post].md"}'),g={name:"201806/20180427 3 Python template libraries compared.md"};function h(u,s,m,f,y,b){const t=o("Link");return r(),d("div",null,[s[34]||(s[34]=e(`<h1 id="_3-個-python-模板庫比較" tabindex="-1">3 個 Python 模板庫比較 <a class="header-anchor" href="#_3-個-python-模板庫比較" aria-label="Permalink to “3 個 Python 模板庫比較”">​</a></h1><blockquote><p>你的下一個 Python 項目需要一個模板引擎來自動生成 HTML 嗎？這有幾種選擇。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/library-libraries-search.png?itok=xH8xSU_G" alt=""></p><p>在我的日常工作中，我花費大量的時間將各種來源的數據轉化為可讀的信息。雖然很多時候這只是電子表格或某種類型的圖表或其他數據可視化的形式，但也有其他時候，將數據以書面形式呈現是有意義的。</p><p>但我的頭疼地方就是複製和粘貼。如果你要將數據從源頭移動到標準化模板，則不應該複製和粘貼。這很容易出錯，説實話，這會浪費你的時間。</p><p>因此，對於我定期發送的任何遵循一個共同的模式的信息，我傾向於找到某種方法來自動化至少一部分信息。也許這涉及到在電子表格中創建一些公式，一個快速 shell 腳本或其他解決方案，以便使用從外部源提取的信息自動填充模板。</p><p>但最近，我一直在探索 Python 模板來完成從其他數據集創建報告和圖表的大部分工作。</p><p>Python 模板引擎非常強大。我的簡化報告創建的使用案例僅僅觸及了它的皮毛。許多開發人員正在利用這些工具來構建完整的 web 應用程序和內容管理系統。但是，你並不需要有一個複雜的 web 應用程序才能使用 Python 模板工具。</p><h3 id="為什麼選擇模板" tabindex="-1">為什麼選擇模板？ <a class="header-anchor" href="#為什麼選擇模板" aria-label="Permalink to “為什麼選擇模板？”">​</a></h3><p>每個模板工具都不甚相同，你應該閲讀文檔以瞭解其確切的用法。但讓我們創建一個假設的例子。假設我想創建一個簡短的頁面，列出我最近編寫的所有 Python 主題。就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;My Python articles&lt;/title&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;p&gt;These are some of the things I have written about Python:&lt;/p&gt;</span></span>
<span class="line"><span>    &lt;ul&gt;</span></span>
<span class="line"><span>      &lt;li&gt;Python GUIs&lt;/li&gt;</span></span>
<span class="line"><span>      &lt;li&gt;Python IDEs&lt;/li&gt;</span></span>
<span class="line"><span>      &lt;li&gt;Python web scrapers&lt;/li&gt;</span></span>
<span class="line"><span>    &lt;/ul&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>當它僅僅是這三個項目時，維護它是很簡單的。但是當我想添加第四個、第五個或第六十七個時會發生什麼？我可以從包含我所有頁面列表的 CSV 文件或其他數據文件生成它，而不是手動編碼此頁面嗎？我可以輕鬆地為我寫的每個主題創建重複內容嗎？我可以以編程方式更改每個頁面上的文本標題嗎？這就是模板引擎可以發揮作用的地方。</p>`,12)),a("p",null,[s[3]||(s[3]=n("有許多不同的選擇，今天我將與你其中分享三個，順序不分先後：",-1)),l(t,{href:"http://www.makotemplates.org/"},{default:p(()=>[...s[0]||(s[0]=[n("Mako",-1)])]),_:1}),s[4]||(s[4]=n("、 ",-1)),l(t,{href:"http://jinja.pocoo.org/"},{default:p(()=>[...s[1]||(s[1]=[n("Jinja2",-1)])]),_:1}),s[5]||(s[5]=n(" 和 ",-1)),l(t,{href:"https://genshi.edgewall.org/"},{default:p(()=>[...s[2]||(s[2]=[n("Genshi",-1)])]),_:1}),s[6]||(s[6]=n("。",-1))]),s[35]||(s[35]=a("h3",{id:"mako",tabindex:"-1"},[n("Mako "),a("a",{class:"header-anchor",href:"#mako","aria-label":"Permalink to “Mako”"},"​")],-1)),a("p",null,[l(t,{href:"http://www.makotemplates.org/"},{default:p(()=>[...s[7]||(s[7]=[n("Mako",-1)])]),_:1}),s[9]||(s[9]=n(" 是以 MIT 許可證發佈的 Python 模板工具，專為快速展現而設計的（與 Jinja2 不同）。Reddit 已經使用 Mako 來展現他們的網頁，它同時也是 Pyramid 和 Pylons 等 web 框架的默認模板語言。它相當簡單且易於使用。你可以使用幾行代碼來設計模板；支持 Python 2.x 和 3.x，它是一個功能強大且功能豐富的工具，具有",-1)),l(t,{href:"http://docs.makotemplates.org/en/latest/"},{default:p(()=>[...s[8]||(s[8]=[n("良好的文檔",-1)])]),_:1}),s[10]||(s[10]=n("，這一點我認為是必須的。其功能包括過濾器、繼承、可調用塊和內置緩存系統，這些系統可以被大型或複雜的 web 項目導入。",-1))]),s[36]||(s[36]=a("h3",{id:"jinja2",tabindex:"-1"},[n("Jinja2 "),a("a",{class:"header-anchor",href:"#jinja2","aria-label":"Permalink to “Jinja2”"},"​")],-1)),a("p",null,[s[12]||(s[12]=n("Jinja2 是另一個快速且功能全面的選項，可用於 Python 2.x 和 3.x，遵循 BSD 許可證。Jinja2 從功能角度與 Mako 有很多重疊，因此對於新手來説，你在兩者之間的選擇可能會歸結為你喜歡的格式化風格。Jinja2 還將模板編譯為字節碼，並具有 HTML 轉義、沙盒、模板繼承和模板沙盒部分的功能。其用户包括 Mozilla、 SourceForge、 NPR、 Instagram 等，並且還具有",-1)),l(t,{href:"http://jinja.pocoo.org/docs/2.10/"},{default:p(()=>[...s[11]||(s[11]=[n("強大的文檔",-1)])]),_:1}),s[13]||(s[13]=n("。與 Mako 在模板內部使用 Python 邏輯不同的是，Jinja2 使用自己的語法。",-1))]),s[37]||(s[37]=a("h3",{id:"genshi",tabindex:"-1"},[n("Genshi "),a("a",{class:"header-anchor",href:"#genshi","aria-label":"Permalink to “Genshi”"},"​")],-1)),a("p",null,[l(t,{href:"https://genshi.edgewall.org/"},{default:p(()=>[...s[14]||(s[14]=[n("Genshi",-1)])]),_:1}),s[15]||(s[15]=n(" 是我會提到的第三個選擇。它是一個 XML 工具，具有強大的模板組件，所以如果你使用的數據已經是 XML 格式，或者你需要使用網頁以外的格式，Genshi 可能成為你的一個很好的解決方案。HTML 基本上是一種 XML（好吧，不是精確的，但這超出了本文的範圍，有點賣弄學問了），因此格式化它們非常相似。由於我通常使用的很多數據都是 XML 或其他類型的數據，因此我非常喜歡使用我可以用於多種事物的工具。",-1))]),s[38]||(s[38]=e(`<p>發行版目前僅支持 Python 2.x，儘管 Python 3 支持存在於主幹中，但我提醒你，它看起來並沒有得到有效的開發。Genshi 遵循 BSD 許可證提供。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>因此，在上面的假設示例中，我不會每次寫新主題時都更新 HTML 文件，而是通過編程方式對其進行更新。我可以創建一個模板，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;My Python articles&lt;/title&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;p&gt;These are some of the things I have written about Python:&lt;/p&gt;</span></span>
<span class="line"><span>    &lt;ul&gt;</span></span>
<span class="line"><span>      %for topic in topics:</span></span>
<span class="line"><span>      &lt;li&gt;\${topic}&lt;/li&gt;</span></span>
<span class="line"><span>      %endfor</span></span>
<span class="line"><span>    &lt;/ul&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>然後我可以使用我的模板庫來迭代每個主題，比如使用 Mako，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from mako.template import Template</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mytemplate = Template(filename=&#39;template.txt&#39;)</span></span>
<span class="line"><span>print(mytemplate.render(topics=(&quot;Python GUIs&quot;,&quot;Python IDEs&quot;,&quot;Python web scrapers&quot;)))</span></span></code></pre></div><p>當然，在現實世界的用法中，我不會將這些內容手動地列在變量中，而是將它們從外部數據源（如資料庫或 API）中提取出來。</p>`,7)),a("p",null,[s[17]||(s[17]=n("這些不是僅有的 Python 模板引擎。如果你正在開始創建一個將大量使用模板的新項目，那麼你考慮的可能不僅僅是這三種選擇。在 ",-1)),l(t,{href:"https://wiki.python.org/moin/Templating"},{default:p(()=>[...s[16]||(s[16]=[n("Python 維基",-1)])]),_:1}),s[18]||(s[18]=n("上查看更全面的列表，以獲得更多值得考慮的項目。",-1))]),s[39]||(s[39]=a("hr",null,null,-1)),a("p",null,[s[20]||(s[20]=n("via: ",-1)),l(t,{href:"https://opensource.com/resources/python/template-libraries"},{default:p(()=>[...s[19]||(s[19]=[n("https://opensource.com/resources/python/template-libraries",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=n("作者：",-1)),l(t,{href:"https://opensource.com/users/jason-baker"},{default:p(()=>[...s[21]||(s[21]=[n("Jason Baker",-1)])]),_:1}),s[26]||(s[26]=n(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[22]||(s[22]=[n("lujun9972",-1)])]),_:1}),s[27]||(s[27]=n(" 譯者：",-1)),l(t,{href:"https://github.com/MjSeven"},{default:p(()=>[...s[23]||(s[23]=[n("MjSeven",-1)])]),_:1}),s[28]||(s[28]=n(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[24]||(s[24]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[31]||(s[31]=n("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[29]||(s[29]=[n("LCTT",-1)])]),_:1}),s[32]||(s[32]=n(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:p(()=>[...s[30]||(s[30]=[n("Linux中國",-1)])]),_:1}),s[33]||(s[33]=n(" 榮譽推出",-1))])])}const x=i(g,[["render",h]]);export{T as __pageData,x as default};
